def transform(grid):
    from collections import Counter
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]
    seen = set()
    for y in range(h):
        for x in range(w):
            c = grid[y][x]
            if c == bg or (y, x) in seen:
                continue
            stack = [(y, x)]; seen.add((y, x)); pts = []
            while stack:
                a, b = stack.pop(); pts.append((a, b))
                for da, db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na, nb = a+da, b+db
                    if 0 <= na < h and 0 <= nb < w and (na,nb) not in seen and grid[na][nb] == c:
                        seen.add((na,nb)); stack.append((na,nb))
            y0, y1 = min(a for a,b in pts), max(a for a,b in pts)
            x0, x1 = min(b for a,b in pts), max(b for a,b in pts)
            area = (y1-y0+1)*(x1-x0+1)
            if area >= 4 and len(pts)/area >= 0.5:
                for a in range(y0,y1+1):
                    for b in range(x0,x1+1): out[a][b] = c
    return out
